.home-examples {
  container: examples / inline-size;
  margin-block: 6rem;
  color: var(--nx-color-foreground);
  font-family: inherit;
  text-align: start;
}
.home-examples h2,
.home-examples h3,
.home-examples p {
  margin: 0;
}
.home-examples-intro {
  margin-block-end: 2rem;
}
.example-eyebrow {
  display: block;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--nx-color-muted-foreground);
  margin-block-end: 1rem;
}
.home-examples-intro h2 {
  font-size: clamp(1.75rem, 4cqi, 2.5rem);
  line-height: 1.15;
  letter-spacing: -0.04em;
  font-weight: 600;
}
.home-examples-intro p {
  color: var(--nx-color-muted-foreground);
  margin-block-start: 1rem;
  max-inline-size: 38rem;
  line-height: 1.6;
}
.home-example-picker {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  margin-block-end: 1.5rem;
}
.home-example-picker button {
  font: inherit;
  text-align: start;
  color: inherit;
  background: transparent;
  border: 1px solid var(--nx-color-border-default);
  border-radius: 0.75rem;
  padding: 1rem;
  cursor: pointer;
  display: grid;
  grid-template-columns: 2rem 1fr;
  gap: 0.375rem 0.5rem;
  transition:
    background 160ms,
    border-color 160ms;
}
.home-example-picker button[aria-pressed='true'] {
  background: var(--nx-color-container);
  border-color: var(--nx-color-foreground);
}
.home-example-picker button:focus-visible {
  outline: 2px solid var(--nx-color-primary-background);
  outline-offset: 3px;
}
.home-example-picker strong {
  font-weight: 600;
}
.home-example-picker button > span:last-child {
  grid-column: 2;
  font-size: 0.8125rem;
  color: var(--nx-color-muted-foreground);
}
.example-number {
  font-family: monospace;
  font-size: 0.75rem;
  color: var(--nx-color-muted-foreground);
  padding-block-start: 0.125rem;
}
.home-example-frame {
  border: 1px solid var(--nx-color-border-default);
  border-radius: 1rem;
  background: var(--nx-color-container);
}
.home-example-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-block-end: 1px solid var(--nx-color-border-default);
  font-size: 0.8125rem;
  color: var(--nx-color-muted-foreground);
}
.home-example-bar strong {
  color: var(--nx-color-foreground);
  font-weight: 600;
}
.home-example-bar > div {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.example-bar-divider {
  padding-inline: 0.5rem;
}
.home-example-preview {
  padding: clamp(1rem, 5cqi, 4rem);
  min-inline-size: 0;
  background: var(--nx-color-background);
  border-radius: 0 0 1rem 1rem;
}
.home-example-preview:focus-visible {
  outline: 2px solid var(--nx-color-primary-background);
  outline-offset: -3px;
}
.example-form {
  max-inline-size: 40rem;
  margin-inline: auto;
}
.example-heading h3 {
  font-size: clamp(1.5rem, 3cqi, 2rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.035em;
}
.example-heading p {
  margin-block-start: 0.75rem;
  line-height: 1.6;
  color: var(--nx-color-muted-foreground);
  font-size: 0.875rem;
}
.example-identity,
.example-summary {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
  margin-block: 2rem;
}
.example-avatar {
  display: grid;
  place-items: center;
  inline-size: 3rem;
  block-size: 3rem;
  border-radius: 0.75rem;
  background: var(--nx-color-primary-background);
  color: var(--nx-color-primary-foreground);
  font-size: 1.5rem;
  font-weight: 600;
}
.example-identity p,
.example-summary p {
  color: var(--nx-color-muted-foreground);
  font-size: 0.8125rem;
  margin-block-start: 0.25rem;
}
.example-badge {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--nx-color-border-default);
  background: var(--nx-color-container);
  border-radius: 2rem;
  padding: 0.25rem 0.625rem;
  font-size: 0.6875rem;
  white-space: nowrap;
}
.example-identity > .example-badge {
  margin-inline-start: auto;
}
.example-fields {
  display: grid;
  gap: 1.25rem;
  margin-block-end: 2rem;
}
.example-fields label,
.example-field,
.example-toolbar label {
  display: grid;
  gap: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 500;
}
.example-preference {
  display: flex;
  gap: 1rem;
  align-items: center;
  justify-content: space-between;
  padding-block: 1.25rem;
  border-block-start: 1px solid var(--nx-color-border-default);
}
.example-preference label {
  font-size: 0.875rem;
  font-weight: 500;
}
.example-preference p {
  font-size: 0.8125rem;
  color: var(--nx-color-muted-foreground);
  margin-block-start: 0.25rem;
  line-height: 1.5;
}
.example-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-block-start: 1.5rem;
}
.example-footer > span,
.example-result {
  font-size: 0.75rem;
  color: var(--nx-color-muted-foreground);
}
.example-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 2rem;
  padding-block: 1.5rem;
  border-block: 1px solid var(--nx-color-border-default);
}
.example-metrics div {
  display: grid;
  gap: 0.5rem;
}
.example-metrics strong {
  font-size: 2rem;
  font-weight: 500;
  letter-spacing: -0.04em;
}
.example-metrics span {
  font-size: 0.75rem;
  color: var(--nx-color-muted-foreground);
}
.example-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-block-end: 1rem;
}
.example-toolbar label {
  inline-size: min(100%, 18rem);
}
.example-table-wrap {
  overflow: auto;
}
.example-table {
  inline-size: 100%;
  border-collapse: collapse;
  text-align: start;
  font-size: 0.8125rem;
  white-space: nowrap;
}
.example-table th,
.example-table td {
  padding: 1rem 0.75rem;
  border-block-end: 1px solid var(--nx-color-border-default);
  text-align: start;
}
.example-table th {
  font-weight: 500;
}
.example-table thead {
  color: var(--nx-color-muted-foreground);
  font-size: 0.75rem;
}
.example-result {
  margin-block-start: 1rem !important;
}
.example-onboarding {
  max-inline-size: 44rem;
  margin-inline: auto;
}
.example-steps {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0;
  margin: 0 0 3rem;
  list-style: none;
}
.example-steps li {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
  font-size: 0.75rem;
  color: var(--nx-color-muted-foreground);
}
.example-steps li > span {
  border: 1px solid var(--nx-color-border-default);
  border-radius: 50%;
  inline-size: 1.75rem;
  block-size: 1.75rem;
  display: grid;
  place-items: center;
}
.example-steps [aria-current='step'],
.example-steps [data-complete='true'] {
  color: var(--nx-color-foreground);
}
.example-steps [aria-current='step'] > span {
  background: var(--nx-color-primary-background);
  color: var(--nx-color-primary-foreground);
  border-color: transparent;
}
.example-onboarding-body {
  max-inline-size: 30rem;
  margin-inline: auto;
  min-block-size: 20rem;
}
.example-onboarding-body .example-heading {
  margin-block-end: 2rem;
}
.example-choices {
  border: 0;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0.75rem;
}
.example-choices legend {
  font-size: 0.8125rem;
  margin-block-end: 0.75rem;
}
.example-choices label {
  border: 1px solid var(--nx-color-border-default);
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
  font-size: 0.875rem;
}
.example-choices input {
  accent-color: var(--nx-color-primary-background);
}
.example-code pre {
  overflow: auto;
  max-block-size: 32rem;
  font-size: 0.8125rem;
  line-height: 1.7;
  margin: 0;
  padding-block: 1rem;
}
.home-examples-note {
  color: var(--nx-color-muted-foreground);
  font-size: 0.75rem;
  margin-block-start: 1rem !important;
}
@container examples (min-width: 40rem) {
  .home-example-picker {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .example-fields {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
